"""Disposable complete production DDL comparison; baseline read through git show."""
import hashlib
import ast
import json
import platform
import re
import sqlite3
import subprocess
import sys
import tempfile
from datetime import datetime, timezone
from pathlib import Path

from repo_catalog.adapters.sqlite.exchange import LOCAL_COLUMNS
from repo_catalog.adapters.sqlite.schema import DDL_SHA256, SCHEMA_VERSION, schema_sql

ROOT = Path.cwd()
BASE = 'db3a5ecfbf95b4c1318198aa308ca6dc749876a1'
COMPOSER = 'src/repo_catalog/adapters/sqlite/schema.py'
BASE_COMPOSER = subprocess.check_output(['git', 'show', f'{BASE}:{COMPOSER}'], cwd=ROOT, text=True)
RESOURCE_NAMES = re.findall(r'"([a-z_0-9]+\.sql)"', BASE_COMPOSER)
BASE_EXCHANGE = subprocess.check_output(['git', 'show', f'{BASE}:src/repo_catalog/adapters/sqlite/exchange.py'], cwd=ROOT, text=True)
BASE_LOCAL_COLUMNS = next(ast.literal_eval(node.value) for node in ast.parse(BASE_EXCHANGE).body if isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id == 'LOCAL_COLUMNS' for target in node.targets))


def quote(name):
    return '"' + name.replace('"', '""') + '"'


def inventory(ddl):
    with sqlite3.connect(':memory:', autocommit=True) as db:
        db.execute('PRAGMA foreign_keys=ON')
        db.execute('PRAGMA recursive_triggers=ON')
        db.executescript(ddl)
        rows = db.execute("SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' ORDER BY type,name").fetchall()
        objects = {kind: {} for kind in ('table', 'view', 'trigger', 'index')}
        for kind, name, table, sql in rows:
            objects[kind][name] = {'table': table, 'sql_sha256': hashlib.sha256(sql.encode()).hexdigest()}
        tables = {}
        for name in objects['table']:
            info = db.execute(f'PRAGMA table_xinfo({quote(name)})').fetchall()
            tables[name] = [{'name': r[1], 'type': r[2], 'not_null': bool(r[3]), 'default': r[4], 'primary_key_position': r[5], 'hidden': r[6]} for r in info]
        resource_fks = {name: [list(r) for r in db.execute(f'PRAGMA foreign_key_list({quote(name)})')] for name in ('issue_resources', 'review_resources')}
        require_empty = db.execute('PRAGMA foreign_key_check').fetchall()
        integrity = [r[0] for r in db.execute('PRAGMA integrity_check')]
        assert require_empty == [] and integrity == ['ok']
        return {'ddl_sha256': hashlib.sha256(ddl.encode()).hexdigest(), 'object_counts': {k: len(v) for k, v in objects.items()}, 'objects': objects, 'table_columns': tables, 'current_resource_foreign_keys': resource_fks, 'foreign_key_check': require_empty, 'integrity_check': integrity}


with tempfile.TemporaryDirectory(prefix='catalog3-baseline-ddl-') as stage:
    resources = []
    for name in RESOURCE_NAMES:
        contents = subprocess.check_output(['git', 'show', f'{BASE}:src/repo_catalog/resources/{name}'], cwd=ROOT, text=True)
        (Path(stage) / name).write_text(contents)
        resources.append(contents)
    baseline = inventory('\n'.join(resources))
    baseline['schema_version'] = int(re.search(r'SCHEMA_VERSION = (\d+)', BASE_COMPOSER)[1])
    baseline['input_file_sha256'] = {COMPOSER: hashlib.sha256(BASE_COMPOSER.encode()).hexdigest(), 'src/repo_catalog/adapters/sqlite/exchange.py': hashlib.sha256(BASE_EXCHANGE.encode()).hexdigest(), **{f'src/repo_catalog/resources/{name}': hashlib.sha256(contents.encode()).hexdigest() for name, contents in zip(RESOURCE_NAMES, resources)}}
current = inventory(schema_sql())
current['schema_version'] = SCHEMA_VERSION
current['input_file_sha256'] = {name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest() for name in baseline['input_file_sha256']}
assert current['ddl_sha256'] == DDL_SHA256.hex()
object_changes = {}
for kind in baseline['objects']:
    before, after = baseline['objects'][kind], current['objects'][kind]
    object_changes[kind] = {'added': sorted(after.keys() - before.keys()), 'removed': sorted(before.keys() - after.keys()), 'modified': sorted(k for k in before.keys() & after.keys() if before[k]['sql_sha256'] != after[k]['sql_sha256'])}
column_changes = {}
for table in baseline['table_columns'].keys() | current['table_columns'].keys():
    before = {c['name']: c for c in baseline['table_columns'].get(table, [])}
    after = {c['name']: c for c in current['table_columns'].get(table, [])}
    change = {'added': sorted(after.keys() - before.keys()), 'removed': sorted(before.keys() - after.keys()), 'modified': sorted(k for k in before.keys() & after.keys() if before[k] != after[k])}
    if any(change.values()):
        column_changes[table] = change
generated = {}
for table in ('issue_resources', 'review_resources'):
    before = {c['name']: c for c in baseline['table_columns'][table] if c['hidden'] in (2, 3)}
    after = {c['name']: c for c in current['table_columns'][table] if c['hidden'] in (2, 3)}
    assert before == after
    generated[table] = sorted(after)
assert current['current_resource_foreign_keys'] == baseline['current_resource_foreign_keys']
assert column_changes == {'issue_resources': {'added': ['field_evidence_json'], 'removed': [], 'modified': []}, 'review_resources': {'added': ['field_evidence_json'], 'removed': ['title'], 'modified': []}}
missing_policy = {table: sorted(set(columns) - {c['name'] for c in current['table_columns'][table]}) for table, columns in LOCAL_COLUMNS.items()}
baseline_missing_policy = {table: sorted(set(columns) - {c['name'] for c in baseline['table_columns'][table]}) for table, columns in BASE_LOCAL_COLUMNS.items()}
assert not any(missing_policy.values())
assert LOCAL_COLUMNS == {'repositories': {'preferred_repository_endpoint_id'}}
script_path = Path('/tmp/schema_inventory_current15.py')
script = script_path.read_text() if script_path.is_file() else json.loads((ROOT / 'docs/current-state-schema-inventory.json').read_text())['reproduction_script']
report = {'run_id': '2026-10-09-current-state-schema-inventory', 'scope': 'Disposable fresh complete production DDL comparison; no retained databases, migration or live sources', 'base_commit': BASE, 'working_head': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(), 'working_tree_is_uncommitted': True, 'observed_at_utc': datetime.now(timezone.utc).isoformat(), 'runtime': {'python': sys.version.split()[0], 'sqlite': sqlite3.sqlite_version, 'platform': platform.platform()}, 'composition': RESOURCE_NAMES, 'baseline': baseline, 'current': current, 'object_changes': object_changes, 'column_changes': column_changes, 'contract_checks': {'current_generated_discriminators_preserved': generated, 'current_resource_native_foreign_keys_preserved': True, 'review_title_absent': True, 'baseline_local_column_policy': {t: sorted(c) for t, c in BASE_LOCAL_COLUMNS.items()}, 'baseline_absent_local_column_policy_entries': baseline_missing_policy, 'local_column_policy': {t: sorted(c) for t, c in LOCAL_COLUMNS.items()}, 'absent_local_column_policy_entries': missing_policy, 'new_history_tables': object_changes['table']['added']}, 'commands': ['uv run --no-sync python /tmp/schema_inventory_current15.py'], 'reproduction_script': script}
(ROOT / 'docs/current-state-schema-inventory.json').write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n')
print(json.dumps({'before': baseline['object_counts'], 'after': current['object_counts'], 'column_changes': column_changes, 'object_changes': object_changes, 'ddl_sha256': current['ddl_sha256']}, indent=2))
